String * tokenizer(const char * text, const char ** delims, int * len) {
    *len = 1;
    for (int i = 0; delims[i] != NULL; i++) {
        int ind = find_substring(text, delims[i]);
        if (ind >= 0) {
            int tailLen;
            String * tail = tokenizer(text+ind+strlen(delims[i]), delims, &tailLen);
            *len = 2 + tailLen;
            char * token1 = malloc((ind+1)*sizeof(char));
            strncpy(token1, text, ind);
            String * list = malloc(3*sizeof(String));
            list[0] = token1;
            list[1] = delims[i];
            memcpy(list+2, tail, sizeof(String)*tailLen);
            return list;
        }    
    }
    char * token1 = malloc((strlen(text)+1)*sizeof(char));
    strcpy(token1, text);
    String * list = malloc(2*sizeof(String));
    list[0] = token1;
    return list;
}

